import CryptoKit
import Foundation
import XCTest

@testable import CiaobotAuthority

/// The shared vectors file, generated by the Python reference.
enum Vectors {
    static let url: URL = {
        // mac/Tests/CiaobotAuthorityTests/TestSupport.swift -> repo root
        var url = URL(fileURLWithPath: #filePath)
        for _ in 0..<4 { url.deleteLastPathComponent() }
        return url.appendingPathComponent("tests/vectors/chat_authority_v1.json")
    }()

    static let doc: [String: JSONValue] = {
        let data = try! Data(contentsOf: url)
        return try! JSON.parse(Array(data)).objectValue!
    }()

    static func object(_ v: JSONValue?) -> [String: JSONValue] { v!.objectValue! }
    static func string(_ o: [String: JSONValue], _ k: String) -> String { o[k]!.stringValue! }
    static func hex(_ o: [String: JSONValue], _ k: String) -> [UInt8] { Hex.decode(o[k]!.stringValue!)! }

    static var keys: [String: JSONValue] { object(doc["keys"]) }
    static var operatorPublic: [UInt8] { hex(keys, "operator_public_x963_hex") }
    static var eventSeed: [UInt8] { hex(keys, "event_seed_hex") }
    static var stateKey: [UInt8] { hex(keys, "state_key_hex") }
}

/// Test-only operator signing with the vectors' public test key (CryptoKit
/// ECDSA is randomized, so signatures are valid but not byte-equal to Python's).
struct OperatorTestSigner {
    let key: P256.Signing.PrivateKey
    let keyID: String

    init(scalarHex: String? = nil) {
        let scalar = Hex.decode(scalarHex ?? Vectors.string(Vectors.keys, "operator_private_scalar_hex"))!
        key = try! P256.Signing.PrivateKey(rawRepresentation: Data(scalar))
        keyID = sha256Hex(Array(key.publicKey.x963Representation))
    }

    func sign(_ kind: String, _ counter: Int64, principal: String = "op", _ params: [String: JSONValue],
              payload: [UInt8] = []) -> SignedCommand {
        let command = Command(kind: kind, counter: counter, principal: principal, params: params, payload: payload, keyID: keyID)
        let sig = try! key.signature(for: Data(command.signingBytes()))
        return SignedCommand(command: command, signature: Array(sig.rawRepresentation))
    }
}

final class MemoryStorage: AuthorityStorage {
    var blob: [UInt8]?
    var failWrites = false
    init(_ blob: [UInt8]? = nil) { self.blob = blob }
    func read() throws -> [UInt8]? { blob }
    func write(_ data: [UInt8]) throws {
        if failWrites { throw StoreError("injected write failure") }
        blob = data
    }
}

final class MemoryAnchor: CounterAnchor {
    var record: AnchorRecord?
    var failAdvance = false
    init(_ record: AnchorRecord? = AnchorRecord(counter: 0)) { self.record = record }
    func read() throws -> AnchorRecord {
        guard let record else { throw AuthorityError("anchor_missing") }
        return record
    }
    func advance(to: Int64, blobSHA256: [UInt8]) throws {
        if failAdvance { throw StoreError("injected advance failure") }
        let current = try read()
        guard to == current.counter + 1 else { throw StoreError("anchor only moves forward by one") }
        record = AnchorRecord(counter: to, currentDigest: blobSHA256, previousDigest: current.currentDigest)
    }
}

func makeAuthority(
    ids: [String], storage: MemoryStorage = MemoryStorage(), anchor: MemoryAnchor = MemoryAnchor(),
    operatorPublic: [UInt8]? = nil
) throws -> ChatAuthority {
    var iterator = ids.makeIterator()
    return try ChatAuthority(
        eventSigner: try EventSigner(seed: Vectors.eventSeed), stateMAC: try StateMAC(key: Vectors.stateKey),
        operatorKey: try OperatorVerifier(publicKeyX963: operatorPublic ?? Vectors.operatorPublic),
        storage: storage, anchor: anchor, newID: { iterator.next() ?? "exhausted-\(UUID().uuidString)" })
}

func temporaryDirectory(_ name: String = "authority") throws -> String {
    // Short: a Unix socket path must fit in 104 bytes.
    let base = NSTemporaryDirectory() + "ca-" + String(UUID().uuidString.prefix(8))
    try FileManager.default.createDirectory(atPath: base, withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
    return base
}
